function efficiencyData(rs) { const groups = new Map(); rs.forEach(r => { const k = r['GĐV thụ lý'] || 'Chưa có mã'; if (!groups.has(k))
    groups.set(k, []); groups.get(k).push(r); }); return [...groups].map(([key, rows]) => { const m = gdvBacklogStats(rows), t = rows.filter(r => r._state === 'Tồn'); return { key, ...m, over90: m.b[3], avgAge: t.length ? sum(t, 'Số ngày tồn') / t.length : null }; }).sort((a, b) => b.backlog - a.backlog || b.avgAge - a.avgAge || a.key.localeCompare(b.key)); }
