function efficiencySuggestionStats(rs) { const s = stats(rs), a = efficiencyData(rs), valid = s.t.filter(r => Number.isFinite(Number(r['Tiền ước/duyệt BT'])) && Number(r['Tiền ước/duyệt BT']) > 0), high = a[0], low = a[a.length - 1]; return { total: rs.length, gdv: a.length, backlog: s.t.length, avgAge: s.t.length ? sum(s.t, 'Số ngày tồn') / s.t.length : null, small: valid.filter(r => Number(r['Tiền ước/duyệt BT']) < 1e7).length, large: valid.filter(r => Number(r['Tiền ước/duyệt BT']) >= 5e7).length, unknown: s.t.length - valid.length, old: s.t.filter(r => Number(r['Số ngày tồn']) > 90).length, mid: s.t.filter(r => Number(r['Số ngày tồn']) > 45 && Number(r['Số ngày tồn']) <= 90).length, high, low, ratio: low && low.backlog ? high.backlog / low.backlog : null, avgCases: a.length ? rs.length / a.length : null }; }
